<?php namespace App\Filament\Resources\StudentClubResource\RelationManagers;use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\RelationManagers\RelationManager;use Filament\Resources\Table;use Filament\Tables;use Illuminate\Support\Facades\DB;class MembersRelationManager extends RelationManager{protected static string $relationship='members';protected static ?string $title='Состав';public static function form(Form $f):Form{return $f->schema([Forms\Components\Select::make('student_id')->label('Студент')->options(fn()=>DB::table('students')->where('status','active')->orderBy('last_name')->get()->mapWithKeys(fn($s)=>[$s->id=>trim($s->last_name.' '.$s->first_name)]))->searchable()->required(),Forms\Components\TextInput::make('role')->label('Роль')->default('participant')->required(),Forms\Components\DatePicker::make('joined_on')->label('Вступил')->default(now()),Forms\Components\DatePicker::make('left_on')->label('Выбыл')]);}public static function table(Table $t):Table{return $t->columns([Tables\Columns\TextColumn::make('student_id')->label('Студент')->formatStateUsing(fn($s)=>($x=DB::table('students')->where('id',$s)->first())?trim($x->last_name.' '.$x->first_name):'—'),Tables\Columns\TextColumn::make('role')->label('Роль'),Tables\Columns\TextColumn::make('joined_on')->label('С')->date('d.m.Y'),Tables\Columns\TextColumn::make('left_on')->label('По')->date('d.m.Y')])->headerActions([Tables\Actions\CreateAction::make()->label('Добавить')])->actions([Tables\Actions\EditAction::make(),Tables\Actions\DeleteAction::make()]);}}